// This file is generated by AI.

// 选项卡右键菜单的**内容** (数据, 不是界面)。
//
// 单独成模块是为了能用单测固定住"每个场景的菜单项一个都不能少"这条硬约束 —— 放在组件里
// 就只能靠人点一遍。两处别"顺手改掉": 「关闭同类型」**包含当前这一张**, 因此永远可用、不需要
// 置灰; 「关闭其它」「关闭其它类型」是**条件出现**, 不是"永远列出但置灰" —— 一串永远点不动的
// 灰项很难用。
//
// `buildTabMenu` 返回的就是 `ContextMenu` 直接能渲染的数据 (含 `onClick`), 组件不参与
// 决定"有哪些项"。

import type { IconName } from '../ui/icons';
import type { WorkbenchTabItem } from './model';
import { orderTabs } from './order';

export interface TabMenuItem {
  key: string;
  label: string;
  iconName?: IconName;
  disabled?: boolean;
  separator?: boolean;
  onClick?: () => void;
}

/** 判断选项卡是否有未保存改动 (由调用方注入, 菜单模块不碰 store)。 */
export type DirtyPredicate = (tab: WorkbenchTabItem) => boolean;

export interface TabMenuActions {
  closeTab: (tab: WorkbenchTabItem) => void;
  closeMany: (tabs: WorkbenchTabItem[]) => void;
  sortTabs: (ordered: WorkbenchTabItem[]) => void;
  revealInFileManager: (path: string) => void;
  locateInBrowser: (tab: WorkbenchTabItem) => void;
}

/** 有对应磁盘位置的选项卡类型。 */
export function hasLocalEntity(tab: WorkbenchTabItem): boolean {
  return tab.kind === 'scene' || tab.kind === 'resource' || tab.kind === 'config';
}

/**
 * 选项卡对应的磁盘路径。
 *
 * 只有场景/资源/配置三种卡有 `path`; 其余类型返回 null。写成类型收窄而不是 `as` 强转,
 * 免得以后有人给别的 kind 加了 `path` 却以为这里会自动跟上。
 */
export function localPathOf(tab: WorkbenchTabItem): string | null {
  if (tab.kind === 'scene' || tab.kind === 'resource' || tab.kind === 'config') return tab.path;
  return null;
}

/** 定位菜单项的文案随类型变化: 它要指出会跳到**哪一个**浏览器。 */
export function locateLabel(tab: WorkbenchTabItem): string {
  if (tab.kind === 'resource') return '定位到资源浏览器';
  if (tab.kind === 'config') return '定位到项目配置';
  return '定位到场景浏览器';
}

export function buildTabMenu(
  tabs: WorkbenchTabItem[],
  tab: WorkbenchTabItem,
  actions: TabMenuActions,
  isDirty: DirtyPredicate
): TabMenuItem[] {
  const currentIndex = tabs.findIndex((item) => item.id === tab.id);
  // 同类型**包含自己**: 「关闭同类型」会连当前这一张一起关 (有未保存改动时照常走关闭确认)。
  const sameKind = tabs.filter((item) => item.kind === tab.kind);
  const otherKind = tabs.filter((item) => item.kind !== tab.kind);
  const rightTabs = currentIndex < 0 ? [] : tabs.slice(currentIndex + 1);
  const savedTabs = tabs.filter((item) => !isDirty(item));

  const sorted = orderTabs(tabs);
  const alreadySorted = tabs.every((item, index) => item.id === sorted[index]?.id);

  const entries: TabMenuItem[] = [
    { key: 'close', label: '关闭', iconName: 'Dismiss', onClick: () => actions.closeTab(tab) },
    {
      key: 'close-right',
      label: '关闭右侧',
      iconName: 'ArrowRight',
      disabled: rightTabs.length === 0,
      onClick: () => actions.closeMany(rightTabs),
    },
  ];

  // 只有一张卡时这两项**不出现**(而不是置灰)
  if (tabs.length > 1) {
    entries.push(
      {
        key: 'close-others',
        label: '关闭其它',
        iconName: 'DocumentMultiple',
        onClick: () => actions.closeMany(tabs.filter((entry) => entry.id !== tab.id)),
      },
      {
        key: 'close-same-kind',
        label: '关闭同类型',
        iconName: tab.icon ?? 'Document',
        onClick: () => actions.closeMany(sameKind),
      }
    );
  }

  if (otherKind.length > 0) {
    entries.push({
      key: 'close-other-kind',
      label: '关闭其它类型',
      iconName: 'AppsList',
      onClick: () => actions.closeMany(otherKind),
    });
  }

  entries.push(
    {
      key: 'close-saved',
      label: '关闭已保存',
      iconName: 'Document',
      disabled: savedTabs.length === 0,
      onClick: () => actions.closeMany(savedTabs),
    },
    {
      key: 'close-all',
      label: '关闭全部',
      iconName: 'DocumentDismiss',
      onClick: () => actions.closeMany([...tabs]),
    },
    { key: 'separator-close', label: '', separator: true },
    {
      key: 'sort',
      label: '整理标签页',
      iconName: 'ArrowSort',
      disabled: alreadySorted,
      onClick: () => actions.sortTabs(sorted),
    },
    { key: 'separator-files', label: '', separator: true }
  );

  if (hasLocalEntity(tab)) {
    const path = localPathOf(tab);
    if (path) {
      entries.push({
        key: 'reveal',
        label: '在文件管理器中打开',
        iconName: 'OpenFolder',
        onClick: () => actions.revealInFileManager(path),
      });
    }
    entries.push({
      key: 'locate',
      label: locateLabel(tab),
      iconName: 'TabDesktop',
      onClick: () => actions.locateInBrowser(tab),
    });
  }

  // 首尾与相邻的分隔符直接去掉: 菜单里出现孤立的横线很难看
  return entries.filter(
    (item, index) =>
      !item.separator ||
      (index > 0 && index < entries.length - 1 && !entries[index - 1]?.separator && !entries[index + 1]?.separator)
  );
}
